(function(){
  'use strict';
  var MAXLEN = 4000;

  function toBytes(s){
    // UTF-8 编码，保证任意文本可逆
    var out=[];
    for(var i=0;i<s.length;i++){
      var c=s.charCodeAt(i);
      if(c<0x80) out.push(c);
      else if(c<0x800){ out.push(0xC0|(c>>6), 0x80|(c&63)); }
      else if(c>=0xD800 && c<0xDC00 && i+1<s.length){
        var c2=s.charCodeAt(i+1), cp=0x10000+((c-0xD800)<<10)+(c2-0xDC00); i++;
        out.push(0xF0|(cp>>18), 0x80|((cp>>12)&63), 0x80|((cp>>6)&63), 0x80|(cp&63));
      }
      else { out.push(0xE0|(c>>12), 0x80|((c>>6)&63), 0x80|(c&63)); }
    }
    return out;
  }
  function fromBytes(b){
    var s='', i=0;
    while(i<b.length){
      var c=b[i++];
      if(c<0x80) s+=String.fromCharCode(c);
      else if((c&0xE0)===0xC0) s+=String.fromCharCode(((c&31)<<6)|(b[i++]&63));
      else if((c&0xF0)===0xE0) s+=String.fromCharCode(((c&15)<<12)|((b[i++]&63)<<6)|(b[i++]&63));
      else {
        var cp=((c&7)<<18)|((b[i++]&63)<<12)|((b[i++]&63)<<6)|(b[i++]&63);
        cp-=0x10000;
        s+=String.fromCharCode(0xD800+(cp>>10), 0xDC00+(cp&1023));
      }
    }
    return s;
  }

  /* ---- BWT：对所有旋转排序，取末列 ---- */
  function bwt(bytes){
    var n=bytes.length;
    if(!n) return {last:[], index:0};
    var idx=new Array(n);
    for(var i=0;i<n;i++) idx[i]=i;
    idx.sort(function(a,b){
      for(var k=0;k<n;k++){
        var x=bytes[(a+k)%n], y=bytes[(b+k)%n];
        if(x!==y) return x-y;
      }
      return a-b;
    });
    var last=new Array(n), primary=0;
    for(var j=0;j<n;j++){
      last[j]=bytes[(idx[j]+n-1)%n];
      if(idx[j]===0) primary=j;
    }
    return {last:last, index:primary, order:idx};
  }
  function ibwt(last, primary){
    var n=last.length;
    if(!n) return [];
    if(primary<0 || primary>=n) return null;
    var counts=new Array(256).fill(0);
    for(var i=0;i<n;i++) counts[last[i]]++;
    var starts=new Array(256), sum=0;
    for(var c=0;c<256;c++){ starts[c]=sum; sum+=counts[c]; }
    var next=new Array(n), seen=new Array(256).fill(0);
    for(var j=0;j<n;j++){ next[starts[last[j]]+seen[last[j]]++] = j; }
    var out=new Array(n), p=next[primary];
    for(var k=0;k<n;k++){ out[k]=last[p]; p=next[p]; }
    return out;
  }

  /* ---- MTF ---- */
  function mtf(bytes){
    var tbl=[]; for(var i=0;i<256;i++) tbl.push(i);
    var out=[];
    for(var j=0;j<bytes.length;j++){
      var v=bytes[j], pos=tbl.indexOf(v);
      out.push(pos);
      tbl.splice(pos,1); tbl.unshift(v);
    }
    return out;
  }
  function imtf(codes){
    var tbl=[]; for(var i=0;i<256;i++) tbl.push(i);
    var out=[];
    for(var j=0;j<codes.length;j++){
      var pos=codes[j];
      if(pos<0||pos>255) return null;
      var v=tbl[pos];
      out.push(v);
      tbl.splice(pos,1); tbl.unshift(v);
    }
    return out;
  }

  /* ---- RLE（对 MTF 输出的 0 游程做编码：[值, 次数]） ---- */
  function rle(nums){
    var out=[], i=0;
    while(i<nums.length){
      var v=nums[i], n=1;
      while(i+n<nums.length && nums[i+n]===v) n++;
      out.push([v,n]);
      i+=n;
    }
    return out;
  }
  function irle(pairs){
    var out=[];
    for(var i=0;i<pairs.length;i++){
      for(var j=0;j<pairs[i][1];j++) out.push(pairs[i][0]);
    }
    return out;
  }

  function entropy(nums){
    if(!nums.length) return 0;
    var f={};
    for(var i=0;i<nums.length;i++) f[nums[i]]=(f[nums[i]]||0)+1;
    var h=0;
    for(var k in f){ var p=f[k]/nums.length; h -= p*Math.log(p)/Math.LN2; }
    return Math.round(h*1000)/1000;
  }
  function runs(nums){
    if(!nums.length) return 0;
    var r=1;
    for(var i=1;i<nums.length;i++) if(nums[i]!==nums[i-1]) r++;
    return r;
  }

  function pipeline(text){
    var s=String(text||'');
    if(!s) return {value:null, error:'输入为空'};
    var bytes=toBytes(s);
    if(bytes.length>MAXLEN) return {value:null, error:'输入 '+bytes.length+' 字节，超过上限 '+MAXLEN+'（旋转排序是 O(n² log n)）'};
    var t=bwt(bytes);
    var m=mtf(t.last);
    var r=rle(m);
    // 校验可逆
    var back=irle(r);
    var un=imtf(back);
    var orig=ibwt(un, t.index);
    var restored = orig ? fromBytes(orig) : null;
    var zeros=0;
    for(var i=0;i<m.length;i++) if(m[i]===0) zeros++;
    return {value:{
      bytes:bytes, n:bytes.length,
      bwt:t.last, index:t.index,
      mtf:m, rle:r,
      restored:restored, lossless: restored===s,
      stats:{
        srcEntropy:entropy(bytes), bwtEntropy:entropy(t.last), mtfEntropy:entropy(m),
        srcRuns:runs(bytes), bwtRuns:runs(t.last),
        mtfZeros:zeros, mtfZeroPct: m.length?Math.round(zeros/m.length*1000)/10:0,
        rlePairs:r.length, rleRatio: m.length?Math.round(r.length*2/m.length*1000)/10:0
      }
    }, error:''};
  }

  function preview(bytes, limit){
    limit=limit||120;
    var s='';
    for(var i=0;i<Math.min(bytes.length,limit);i++){
      var c=bytes[i];
      s += (c>=32 && c<127) ? String.fromCharCode(c) : ('·');
    }
    return s + (bytes.length>limit?'…':'');
  }

  var API={bwt:bwt, ibwt:ibwt, mtf:mtf, imtf:imtf, rle:rle, irle:irle,
           pipeline:pipeline, toBytes:toBytes, fromBytes:fromBytes,
           entropy:entropy, runs:runs, preview:preview, MAXLEN:MAXLEN};
  if(typeof module!=='undefined' && module.exports) module.exports=API;
  if(typeof window!=='undefined') window.__BwtForge__=API;
})();
